                ["Advanced_EnablePrivilegesTip"] = "Ενεργοποιεί προνόμια (SeTcbPrivilege, SeDebugPrivilege) που η διεργασία ήδη διαθέτει ως Administrator - δεν παρακάμπτει καμία προστασία. Για προχωρημένους χρήστες.",
                ["Advanced_NetworkReset"] = "Επαναφορά Δικτύου & Winsock",
                ["Advanced_NetworkResetTip"] = "Ίδιο αποτέλεσμα με την Πλήρη Επαναφορά Δικτύου της καρτέλας Δίκτυο & Ασφάλεια, εδώ σε συμπυκνωμένη μορφή.",
                ["Advanced_ClearEventLogs"] = "Καθαρισμός Event Logs",
                ["Advanced_ClearEventLogsTip"] = "Αδειάζει εντελώς τα αρχεία καταγραφής συμβάντων. Ελευθερώνει χώρο, αλλά χάνετε το ιστορικό - μην το τρέχετε πριν από αντιμετώπιση προβλήματος.",
                ["Advanced_GcOptimize"] = "Βελτιστοποίηση Μνήμης (GC)",
                ["Advanced_GcOptimizeTip"] = "Εκτελεί .NET Garbage Collection στη διεργασία της ίδιας της εφαρμογής (όχι σε ολόκληρο το σύστημα).",
                ["Advanced_DeepDiagnosticsTip"] = "Εξάγει βασικά στοιχεία συστήματος (OS, RAM, όνομα υπολογιστή) σε αρχείο .txt στην Επιφάνεια Εργασίας.",
                ["Advanced_DeviceManager"] = "Διαχείριση Οδηγών",
                ["Advanced_DeviceManagerTip"] = "Ανοίγει τη Διαχείριση Συσκευών των Windows (devmgmt.msc).",
                ["Advanced_WuTroubleshoot"] = "Επιδιόρθωση Windows Update",
                ["Advanced_WuTroubleshootTip"] = "Τρέχει τον ενσωματωμένο ανιχνευτή/επιδιορθωτή προβλημάτων Windows Update των Windows.",
                ["Advanced_SystemReport"] = "Αναφορά Συστήματος",
                ["Advanced_SystemReportTip"] = "Δημιουργεί πλήρη αναφορά υγείας ενέργειας/υλικού (powercfg /energy) σε αρχείο HTML.",
                ["Advanced_ResetWuServices"] = "Reset Υπηρεσιών Windows Update",
                ["Advanced_ResetWuServicesTip"] = "Σταματά τις υπηρεσίες Windows Update, μετονομάζει τους φακέλους cache (SoftwareDistribution/catroot2) και τις ξεκινά ξανά - διορθώνει κολλημένες/χαλασμένες ενημερώσεις.",
                ["Advanced_CleanXbox"] = "Καθαρισμός Διαπιστευτηρίων Xbox",
                ["Advanced_CleanXboxTip"] = "Διαγράφει τα αποθηκευμένα διαπιστευτήρια σύνδεσης Xbox από τα Windows - χρήσιμο όταν η σύνδεση στο Xbox app/Game Bar έχει κολλήσει.",
                ["Advanced_InstallGpedit"] = "Εγκατάσταση Group Policy Editor",
                ["Advanced_InstallGpeditTip"] = "Εγκαθιστά το Group Policy Editor (gpedit.msc), το οποίο λείπει από τις εκδόσεις Windows Home.",
                ["Advanced_SnippingTip"] = "Ανοίγει το ενσωματωμένο εργαλείο αποκοπής οθόνης των Windows.",
                ["Advanced_Notepad"] = "Σημειωματάριο",
                ["Advanced_NotepadTip"] = "Ανοίγει το Σημειωματάριο (notepad.exe).",
                ["Advanced_Calculator"] = "Αριθμομηχανή",
                ["Advanced_CalculatorTip"] = "Ανοίγει την Αριθμομηχανή των Windows.",
                ["Advanced_ControlPanel"] = "Πίνακας Ελέγχου",
                ["Advanced_ControlPanelTip"] = "Ανοίγει τον κλασικό Πίνακα Ελέγχου (control.exe).",
                ["Advanced_TaskManager"] = "Διαχείριση Εργασιών",
                ["Advanced_TaskManagerTip"] = "Ανοίγει τη Διαχείριση Εργασιών (taskmgr.exe).",
                ["Advanced_RegistryEditor"] = "Επεξεργαστής Μητρώου",
                ["Advanced_RegistryEditorTip"] = "Ανοίγει τον Επεξεργαστή Μητρώου (regedit.exe) - προσοχή σε χειροκίνητες αλλαγές.",
                ["Advanced_GpuReset"] = "Επανεκκίνηση GPU Driver",
                ["Advanced_GpuResetTip"] = "Απενεργοποιεί και επανενεργοποιεί τον οδηγό κάρτας γραφικών - διορθώνει κολλημένη/μαύρη οθόνη χωρίς πλήρη επανεκκίνηση PC.",
                ["Advanced_RefreshListBtn"] = "Ανανέωση Λίστας",
                ["Advanced_OptionalFeaturesDesc"] = "Πλήρης, αναζητήσιμη λίστα όλων των πρόσθετων λειτουργιών Windows.",
                ["System_Kill"] = "Τερματισμός",
                ["System_FindDuplicates"] = "Εύρεση Διπλότυπων",
                ["System_FindLarge"] = "Εύρεση Μεγάλων Αρχείων",
                ["System_OneDrive"] = "OneDrive - Ελευθέρωση Χώρου",
                ["System_GoogleDrive"] = "Google Drive - Μεγάλα Αρχεία",
                ["System_Dropbox"] = "Dropbox - Μεγάλα Αρχεία",
                ["Sys_CloudNotFound"] = "Ο φάκελος δεν βρέθηκε.",
                ["System_StorageDesc"] = "Σαρώνει μόνο προσωπικούς φακέλους (Έγγραφα/Λήψεις/Επιφάνεια/Εικόνες/Βίντεο), ποτέ φακέλους συστήματος.",
                ["System_RecycleBin"] = "Κάδος Ανακύκλωσης",
                ["System_CreatePoint"] = "Δημιουργία Νέου Σημείου",
                ["System_OpenProtectionSettings"] = "Άνοιγμα Ρυθμίσεων Προστασίας",
                ["System_RestoreAction"] = "Επαναφορά",
                ["System_BenchmarkDesc"] = "Ενδεικτική μέτρηση (256MB write/read) - όχι υποκατάστατο εξειδικευμένου εργαλείου όπως CrystalDiskMark. Η ανάγνωση μπορεί να επηρεαστεί από cache του λειτουργικού.",
                ["System_StartBenchmark"] = "Έναρξη Δοκιμής",
                ["System_Write"] = "Εγγραφή (Write)",
                ["System_Read"] = "Ανάγνωση (Read)",
                ["VerHist_Title"] = "Ιστορικό Εκδόσεων",
                ["VerHist_Subtitle"] = "Συνοπτική επισκόπηση - για το πλήρες, αναλυτικό ιστορικό κάθε αλλαγής δείτε το αρχείο HANDOFF.md του project.",
                ["VerHist_510Title"] = "v5.1.0 - Διαχείριση WSL2, ανιχνευτής συγκρούσεων RGB, winget pin/export/import, και άλλα",
                ["VerHist_510Desc"] = "Νέο: διαχείριση WSL2 - δείτε τις διανομές Linux σας, ανοίξτε κέλυφος, ορίστε προεπιλογή, τερματίστε ή καταργήστε πλήρως μία, ενημερώστε το WSL, ή τερματίστε τα όλα, απευθείας από την εφαρμογή. Νέο: ανιχνευτής συγκρούσεων RGB που επισημαίνει όταν τρέχουν ταυτόχρονα δύο ή περισσότερα προγράμματα ελέγχου RGB φωτισμού διαφορετικών κατασκευαστών (π.χ. Corsair iCUE + ASUS Aura Sync), συνηθισμένη αιτία τρεμοπαίγματος. Ο Διαχειριστής Ενημερώσεων Λογισμικού υποστηρίζει πλέον winget pin, ώστε να κλειδώνετε μια εφαρμογή από μελλοντικές αναβαθμίσεις, καθώς και εξαγωγή/εισαγωγή της λίστας εγκατεστημένων εφαρμογών σας για μεταφορά σε άλλον υπολογιστή.",
                ["VerHist_520Title"] = "v5.2.0 - Ενοποιήσεις καρτελών, διορθώσεις FPS/Widget, MIT+GPL3 άδεια, και άλλα",
                ["VerHist_520Desc"] = "Η κάρτα ενημερώσεων λογισμικού στη Βελτιστοποίηση απέκτησε κυκλικό, κινούμενο κουμπί σάρωσης (όπως των οδηγών) αντί για απλό κουμπί - οι παλιές συντομεύσεις ενημερώσεων αφαιρέθηκαν από την Αρχική. Η τάση υγείας δίσκου μετακινήθηκε στο τέλος της καρτέλας Υγεία & Συντήρηση. Τα Ενσωματωμένα Στοιχεία Windows και οι Πρόσθετες Λειτουργίες Windows ενοποιήθηκαν σε μία κάρτα (καρτέλα Εφαρμογές & Bloat), όπως και η εύρεση διπλότυπων αρχείων με τα εργαλεία αποθηκευτικού χώρου (καρτέλα Σύστημα). Το Ιστορικό Εκδόσεων ενσωματώθηκε ως tab στο παράθυρο Βοήθεια/Οδηγίες - η συντόμευσή του στο πλευρικό μενού αντικαταστάθηκε από το Ιστορικό Πρόχειρου. Οι καρτέλες Μενού και Γλώσσα στις Ρυθμίσεις Εμφάνισης ενοποιήθηκαν. Διορθώθηκε bug που εμπόδιζε μόνιμα την εμφάνιση FPS στο Widget Επιφάνειας Εργασίας/Παιχνιδιών. Τα skins Microsoft PC Manager/Windows Classic αφαιρέθηκαν από το dropdown θεμάτων - επιλέγονται πλέον αποκλειστικά από την καρτέλα Σκινς. Η Άδεια Χρήσης πλέον εμπεριέχει και το πλήρες κείμενο της GNU GPL v3.0.",
                ["VerHist_530Title"] = "v5.3.0 - Νέο Όνομα: GearWin - Complete PC Care",
                ["VerHist_530Desc"] = "Η εφαρμογή μετονομάστηκε σε \"GearWin\" με υπότιτλο \"Complete PC Care\" (μετά από έλεγχο διαθεσιμότητας ονόματος σε καταστήματα εφαρμογών και μητρώα εμπορικών σημάτων, ώστε να αποφευχθεί σύγκρουση με υπάρχοντα προϊόντα) - το εκτελέσιμο, ο τίτλος του παραθύρου, το εικονίδιο συστήματος, ο installer και η άδεια χρήσης ενημερώθηκαν όλα αντίστοιχα. Το namespace του κώδικα και ο φάκελος δεδομένων χρήστη παραμένουν ίδια, οπότε καμία υπάρχουσα ρύθμιση δεν χάνεται σε αυτή την ενημέρωση.",
                ["VerHist_4100Title"] = "v4.10.0 - Έλεγχος διαρροής κωδικού, αντίγραφο ασφαλείας συστήματος, ενοποιημένη διαχείριση προφίλ, και άλλα",
                ["VerHist_4100Desc"] = "Νέο: έλεγχος αν ένας κωδικός έχει εμφανιστεί σε γνωστές διαρροές δεδομένων, μέσω της βάσης Have I Been Pwned με πλήρη ιδιωτικότητα (μόνο ένα τμήμα του hash φεύγει από τον υπολογιστή). Νέο: αντίγραφο ασφαλείας συστήματος με ένα κλικ μέσω του ενσωματωμένου εργαλείου των Windows, σε ξεχωριστό δίσκο-στόχο. Η διαχείριση προφίλ (ονομασμένα προφίλ + export/import αρχείου) είναι πλέον ενοποιημένη σε μία κάρτα αντί για δύο ξεχωριστές. Η ανίχνευση υγείας δίσκου καλύπτει πλέον αξιόπιστα και τους δίσκους NVMe, όχι μόνο SATA. Η κάρτα μπαταρίας συνδέεται πλέον απευθείας με την ανάλυση χρήσης μπαταρίας ανά εφαρμογή των Windows.",
                ["VerHist_490Title"] = "v4.9.0 - Διαχειριστής clipboard, κρυπτογράφηση φακέλων, GPU/FPS επικάλυψη παιχνιδιών, και άλλα",
                ["VerHist_490Desc"] = "Μεγάλος γύρος λειτουργιών: αναζητήσιμο Ιστορικό Clipboard (Win+Shift+V, ή από το tray) με τοπική, μη κρυπτογραφημένη αποθήκευση - καθαρίζεται όποτε θέλετε. Το Κλείδωμα Φακέλου κρυπτογραφεί οποιονδήποτε φάκελο σε ένα μόνο προστατευμένο με κωδικό αρχείο (AES-256, λειτουργεί σε κάθε έκδοση Windows) και διαγράφει με ασφάλεια το αρχικό. Το Widget Επιφάνειας Εργασίας είναι πλέον το Widget Απόδοσης & Παιχνιδιών - δείχνει επίσης χρήση GPU και εκτιμώμενα FPS κατά τη διάρκεια παιχνιδιών σε πλήρη οθόνη. Η Αρχική έχει τώρα ένα μικρό στιγμιότυπο Ενημερώσεων (drivers/εφαρμογές) ώστε να μην χρειάζεται να ελέγχετε τρία διαφορετικά σημεία. Τα κλειδιά ανάκτησης BitLocker και το ιστορικό συσκευών USB είναι πλέον ορατά μέσα από την εφαρμογή, και η Δίκτυο & Ασφάλεια σας προειδοποιεί πλέον αν το DNS-over-HTTPS παρακάμπτει σιωπηλά τον αποκλεισμό τηλεμετρίας μέσω hosts.",
                ["VerHist_482Title"] = "v4.8.2 - Διόρθωση: αρκετά στοιχεία της διεπαφής έμεναν στην παλιά γλώσσα μέχρι επανεκκίνηση",
                ["VerHist_482Desc"] = "Η αλλαγή γλώσσας ενώ η εφαρμογή τρέχει ενημερώνει πλέον τα πάντα ζωντανά, χωρίς να χρειάζεται κλείσιμο και άνοιγμα ξανά: το μενού του εικονιδίου στο system tray (είναι WinForms, εκτός του κανονικού μηχανισμού binding του WPF), οι συντομεύσεις της οριζόντιας λωρίδας μενού (η εναλλακτική διάταξη του πλευρικού μενού), και το κείμενο ανάπαυσης της γραμμής κατάστασης ενημερώνονται πλέον όλα άμεσα. Διορθώθηκε επίσης το κουμπί εναλλαγής θέματος (Φωτεινή/Σκοτεινή Λειτουργία) - ήταν hardcoded στα αγγλικά και δεν περνούσε καν ποτέ από το σύστημα μετάφρασης, ανεξαρτήτως γλώσσας.",
                ["VerHist_481Title"] = "v4.8.1 - Διόρθωση: το παράθυρο Ιστορικού Εκδόσεων είχε μείνει σε παλιές καταχωρήσεις",
                ["VerHist_481Desc"] = "Το παράθυρο Ιστορικού Εκδόσεων μέσα στην εφαρμογή χρησιμοποιούσε μια εντελώς στατική, hardcoded λίστα καταχωρήσεων αντί να διαβάζει το πραγματικό ιστορικό της τρέχουσας έκδοσης - οπότε οι δύο τελευταίες ενημερώσεις (διορθώσεις RTL/cache για τα Αραβικά, και η προσθήκη Αραβικών & Χίντι) δεν εμφανίζονταν ποτέ εκεί, παρότι το κείμενο υπήρχε ήδη. Διορθώθηκε προσθέτοντας και τις δύο καταχωρήσεις· το παράθυρο πλέον αντικατοπτρίζει την πραγματική, τρέχουσα έκδοση.",
                ["VerHist_480Title"] = "v4.8.0 - Διάταξη RTL για Αραβικά, ταχύτερη εναλλαγή καρτελών, διορθώσεις UI",
                ["VerHist_480Desc"] = "Τα Αραβικά εμφανίζονται πλέον με πραγματική διάταξη από δεξιά προς τα αριστερά (όχι μόνο μεταφρασμένο κείμενο) στο κύριο παράθυρο και σε όλα τα δευτερεύοντα παράθυρα/διαλόγους. Ο έλεγχος εγκατεστημένων για τις Προτεινόμενες Εφαρμογές και η σάρωση υλικού στο «Η Συσκευή Μου» δεν ξανατρέχουν πλέον σε κάθε επίσκεψη καρτέλας - και τα δύο κρατούν cache για όλη τη συνεδρία, με ρητό κουμπί «Ανανέωση» για όποτε άλλαξε κάτι εκτός εφαρμογής. Διορθώθηκε: τα chips συντομεύσεων δημοφιλών λειτουργιών στις Πρόσθετες Λειτουργίες Windows ήταν πολύ μικρά (έλειπε μέγεθος γραμματοσειράς)· το κουμπί «Έλεγχος Ενημερώσεων μέσω Microsoft Store» είναι πλέον στην ίδια γραμμή με τα Σάρωση/Αναβάθμιση Επιλεγμένων αντί για δική του σειρά. Τεκμηριώθηκαν επίσης οι σιωπηλές παράμετροι εγκατάστασης (/VERYSILENT) στο README.",
                ["VerHist_470Title"] = "v4.7.0 - Αραβικά & Χίντι (σύνολο 14 γλωσσών), εμπλουτισμένο μενού tray, δημοσιοποίηση αδειών",
                ["VerHist_470Desc"] = "Προστέθηκαν δύο νέες γλώσσες - Αραβικά και Χίντι - φτάνοντας τις 14 πλήρως μεταφρασμένες γλώσσες. Το μενού του εικονιδίου στο system tray προσφέρει πλέον και συντομεύσεις Γρήγορου Καθαρισμού και Ελέγχου Υγείας, καθώς και ένα επιλέξιμο κουμπί εναλλαγής για το Widget Επιφάνειας Εργασίας, χωρίς να χρειάζεται άνοιγμα του κύριου παραθύρου. Δύο νέες συντομεύσεις πληκτρολογίου: το Ctrl+F εστιάζει στο πλαίσιο αναζήτησης, το Ctrl+H ανοίγει απευθείας τον Πλήρη Έλεγχο Υγείας. Η καρτέλα Άδειας Χρήσης (και ο Installer) δημοσιοποιούν πλέον σωστά τις ενσωματωμένες βιβλιοθήκες τρίτων (LibreHardwareMonitorLib υπό MPL 2.0, PDFsharp υπό MIT).",
                ["VerHist_460Title"] = "v4.6.0 - Υγεία Δίσκου στην Αρχική, Ονομασμένα Προφίλ, Widget Επιφάνειας Εργασίας",
                ["VerHist_460Desc"] = "Η Αρχική δείχνει πλέον ένδειξη υγείας δίσκου S.M.A.R.T. δίπλα στο Health Score. Νέα \"Ονομασμένα Προφίλ\" (καρτέλα Επιπλέον Ρυθμίσεις) - αποθηκεύστε τις πλήρεις ρυθμίσεις σας (θέμα, tweaks, γλώσσα, πλευρικό μενού) με ένα όνομα και εναλλάσσεστε ανάμεσά τους άμεσα, δίπλα στο ήδη υπάρχον αρχείο-βασισμένο Export/Import. Νέο \"Widget Επιφάνειας Εργασίας\" (Ρυθμίσεις Εμφάνισης) - ένα πάντα ορατό, μετακινούμενο widget CPU/RAM/Δικτύου στην επιφάνεια εργασίας σας, ξεχωριστό από το tray popup που ανοίγει με κλικ. Επίσης αρκετές βελτιώσεις απόδοσης/αξιοπιστίας από κάτω: παράλληλο hashing διπλότυπων αρχείων, παράλληλοι έλεγχοι υγείας, 24ωρη cache για τη σάρωση καταλόγου drivers, fuzzy αναζήτηση, ουρά toast ειδοποιήσεων, και αυτόματη ανίχνευση γλώσσας συστήματος στην πρώτη εκκίνηση.",
                ["VerHist_450Title"] = "v4.5.0 - Ολοκλήρωση και των 12 Γλωσσών, Διορθώσεις Windows Classic Skin",
                ["VerHist_450Desc"] = "Η εφαρμογή είναι πλέον πλήρως μεταφρασμένη και στις 12 γλώσσες (Ελληνικά, Αγγλικά, Γερμανικά, Γαλλικά, Ισπανικά, Ιταλικά, Ρωσικά, Κινέζικα, Ιαπωνικά, Πορτογαλικά, Κορεατικά, Τουρκικά) - το γρήγορο μενού επιλογής γλώσσας στο κύριο παράθυρο προσφέρει πλέον όλες. Διορθώθηκε το Windows Classic skin: τα αναπτυσσόμενα μενού, το dropdown του ComboBox και τα γρήγορα μενού του κύριου παραθύρου χρησιμοποιούν πλέον σωστά τετράγωνες γωνίες αντί να παραμένουν στρογγυλεμένα· τρία δευτερεύοντα παράθυρα διαλόγου (Νέα Επιλογή Δεξιού Κλικ, Περαιτέρω Ανάλυση, Έλεγχος Υγείας) που δεν είχαν τις τετράγωνες γωνίες του skin τις αποκτούν πλέον κι αυτά.",
                ["VerHist_444Title"] = "v4.4.4 - Εύρεση Διπλότυπων, Ανοιχτές Θύρες, Tray Widget & Πλήρες Προφίλ",
                ["VerHist_444Desc"] = "Νέα «Εύρεση Διπλότυπων Αρχείων» (Προηγμένα Εργαλεία) - επιλέγετε φάκελο, εντοπίζει αρχεία με ακριβώς το ίδιο περιεχόμενο (μέγεθος + hash). Νέα «Ανοιχτές Θύρες» (Δίκτυο & Ασφάλεια) - δείχνει ποιες θύρες TCP είναι σε ακρόαση και ποια διεργασία τις κατέχει. Η εφαρμογή έχει πλέον εικονίδιο στην περιοχή ειδοποιήσεων με μίνι αναδυόμενο παράθυρο (CPU/RAM/Δίκτυο) χωρίς να χρειάζεται άνοιγμα του κύριου παραθύρου. Η Εξαγωγή/Εισαγωγή Προφίλ (Επιπλέον Ρυθμίσεις) καλύπτει πλέον ΟΛΗ την εμπειρία χρήστη (θέμα, γλώσσα, πλευρικό μενού, καρφιτσωμένες συντομεύσεις), όχι μόνο τα tweaks. Διορθώθηκε επίσης ένα πραγματικό σφάλμα που σταματούσε τη σάρωση Προγραμματισμένων Εργασιών (ίδια ρίζα με προηγούμενη διόρθωση: το PowerShell δεν σειριοποιεί πάντα ένα enum ως κείμενο).",
                ["VerHist_443Title"] = "v4.4.3 - Επέκταση Registry Cleaner, Backup History & Υπενθύμιση Ελέγχου",
                ["VerHist_443Desc"] = "Ο Registry Cleaner σαρώνει πλέον και ορφανά Shared DLLs. Νέο «Ιστορικό Backup Registry» (Υγεία & Συντήρηση) δείχνει και επαναφέρει τα αυτόματα .reg backups κάθε διαγραφής - πριν ήταν προσβάσιμα μόνο χειροκίνητα έξω από την εφαρμογή. Η κάρτα επιπλέον ευρημάτων υγείας στον Πλήρη Έλεγχο Υγείας έχει πλέον κουμπί που πηγαίνει κατευθείαν στην καρτέλα Σύστημα. Οι εφαρμογές εκκίνησης δείχνουν τώρα Χαμηλή/Μέτρια/Υψηλή επίδραση βάσει του πραγματικού μετρημένου χρόνου καθυστέρησης. Η Αρχική υπενθυμίζει ήπια αν δεν έχει τρέξει Πλήρης Έλεγχος Υγείας εδώ και 7+ μέρες.",
                ["VerHist_442Title"] = "v4.4.2 - Διόρθωση: Τα Πλακίδια Ενημερώνονται Μετά τη Βελτιστοποίηση",
                ["VerHist_442Desc"] = "Ο χρήστης ανέφερε ότι μετά το «Βελτιστοποίηση Τώρα» στον Πλήρη Έλεγχο Υγείας, τα πλακίδια αποτελεσμάτων έδειχναν τους ΠΑΛΙΟΥΣ αριθμούς (π.χ. συνέχιζε να λέει «19 καταχωρήσεις registry» ενώ ο πραγματικός καθαρισμός ΕΙΧΕ γίνει - επιβεβαιώθηκε με πραγματικό δοκιμαστικό εύρημα ότι η διαγραφή δουλεύει σωστά). Τώρα, μετά τον καθαρισμό, τα στάδια που καθαρίστηκαν ξανασαρώνονται αυτόματα και όλα τα πλακίδια ενημερώνονται με τα φρέσκα αποτελέσματα. Επίσης, αν ο καθαρισμός registry αποτύχει πραγματικά (π.χ. χωρίς δικαιώματα Διαχειριστή), η εφαρμογή το αναφέρει πλέον ειλικρινά αντί να δηλώνει ψευδώς επιτυχία.",
                ["VerHist_441Title"] = "v4.4.1 - Ενοποιημένος Πλήρης Έλεγχος Υγείας & Συνέπεια Εικονιδίων",
                ["VerHist_441Desc"] = "Ο Γρήγορος Καθαρισμός και ο Πλήρης Έλεγχος Υγείας συγχωνεύτηκαν σε ΕΝΑ σημείο εισόδου (αφαιρέθηκε η διπλή κάρτα στην Αρχική). Ο Πλήρης Έλεγχος Υγείας τώρα δείχνει πραγματική βαθμολογία 0-100 στα αποτελέσματα, εξάγει αναφορά PDF, και σαρώνει επιπλέον την cache περιηγητών μαζί με τον χώρο δίσκου. Το στάδιο «Ίχνη Χρήσης» μετονομάστηκε ρητά σε «Καθαρισμός Registry» και η σάρωση επεκτάθηκε (App Paths, ορφανές καταχωρήσεις αυτόματης εκκίνησης). Τα τελευταία εναπομείναντα emoji εικονίδια (στις κεφαλίδες καρτελών της Βοήθειας και σε 9 κάρτες αλλού στην εφαρμογή) αντικαταστάθηκαν με το ίδιο διανυσματικό σύστημα εικονιδίων, και ο απαλός παλμός τους ενισχύθηκε ώστε να είναι ευδιάκριτος.",
                ["VerHist_440Title"] = "v4.4.0 - Πλήρης Οδηγός Χρήσης με Κινούμενα Εικονίδια",
                ["VerHist_440Desc"] = "Η Βοήθεια ξαναγράφτηκε εντελώς - από 8 σύντομες γενικές παραγράφους (μία ανά καρτέλα) σε αναλυτική επεξήγηση ΚΑΘΕ λειτουργίας και κουμπιού, οργανωμένη ανά καρτέλα και ανά κάρτα (53 ξεχωριστές αναλύσεις), το καθένα με το πραγματικό, κινούμενο (απαλός παλμός) εικονίδιο της αντίστοιχης λειτουργίας - το ίδιο σύστημα εικονιδίων που ήδη χρησιμοποιεί η εφαρμογή, όχι νέα, ασύνδετα εικονίδια.",
                ["VerHist_437Title"] = "v4.3.7 - Εξαγωγή σε PDF, Ευδιάκριτοι Διακόπτες & Chips",
                ["VerHist_437Desc"] = "Η εξαγωγή «Η Συσκευή Μου» γίνεται πλέον σε πραγματικό PDF αρχείο αντί για .txt (νέο PdfExportService, PDFsharp). Διορθώσεις μετά από ζωντανό έλεγχο σε Light Mode: οι διακόπτες (toggle) στη λίστα Πρόσθετων Λειτουργιών Windows ήταν σχεδόν αόρατοι σε ανοιχτόχρωμα θέματα (λευκός κύκλος πάνω σε σχεδόν-λευκό φόντο) - προστέθηκε ορατό περίγραμμα παντού. Τα μπλε chips δημοφιλών λειτουργιών ήταν πολύ σφιχτά, με το κείμενο να μην χωράει άνετα - μεγαλύτερο padding.",
                ["VerHist_436Title"] = "v4.3.6 - Διορθώσεις μετά από Ζωντανό Έλεγχο",
                ["VerHist_436Desc"] = "Το pill «Απεγκατάσταση Εφαρμογών» στον Πλήρη Έλεγχο Υγείας έκοβε στην άκρη του παραθύρου - το παράθυρο πλάτυνε. ΠΡΑΓΜΑΤΙΚΟ bug: η ανανέωση Πρόσθετων Λειτουργιών Windows κρασάριζε ολόκληρη τη σάρωση με «The requested operation requires an element of type 'String', but the target element has type 'Number'» όποτε το PowerShell επέστρεφε την κατάσταση μιας λειτουργίας ως αριθμό αντί για κείμενο - διορθώθηκε ώστε να αναγνωρίζει και τις δύο μορφές, χωρίς να ακυρώνεται πια ολόκληρη η λίστα εξαιτίας μίας λειτουργίας.",
                ["VerHist_435Title"] = "v4.3.5 - Κίνηση Δικτύου Ανά Εφαρμογή, Ταχύτερη Εκκίνηση & Πολλές Διορθώσεις",
                ["VerHist_435Desc"] = "Νέα: Κίνηση δικτύου ανά εφαρμογή (Δίκτυο & Ασφάλεια, μέσω ETW), 40+ νέα unit tests (13 → 54), ταχύτερη εκκίνηση (η αρχικοποίηση CPU/GPU μετρητών μετακινήθηκε σε background thread, δεν καθυστερεί πια το πρώτο άνοιγμα του κύριου παραθύρου), καμία πλέον «κολλημένη» μπάρα προόδου σε εξαίρεση (Έλεγχος Ενημερώσεων μέσω winget/Αποθήκη Οδηγών/Πλήρης Έλεγχος Υγείας - το τελευταίο με νέο κουμπί «Επανάληψη» σε αποτυχία σταδίου). Διορθώσεις μετά από ζωντανό έλεγχο: το γραφικό του Πλήρους Ελέγχου Υγείας δεν κόβεται πια στο παράθυρο και κάθε στάδιο μένει ορατά φωτισμένο τουλάχιστον λίγο, αόρατο κείμενο στον Γρήγορο Καθαρισμό σε σκούρο θέμα, επικαλυπτόμενες κάρτες «Καρφιτσωμένα»/«Ανάλυση Χώρου» στην Αρχική, στενό κουμπί Microsoft Store, μικροσκοπικά κουμπιά στα Ελαφρύτερα Windows, μη διακριτά chips δημοφιλών λειτουργιών, και ΠΡΑΓΜΑΤΙΚΟ bug όπου η ανανέωση των Πρόσθετων Λειτουργιών Windows έδειχνε πάντα «τρέξε ως Διαχειριστής» (ακόμα κι όταν η εφαρμογή ήταν ήδη elevated) αντί για το πραγματικό, αλλοιωμένο (encoding) μήνυμα σφάλματος του PowerShell.",
                ["VerHist_430Title"] = "v4.3.0 - Ειδοποιήσεις, Καταστροφέας Αρχείων, Autologon & Πολλά Ακόμα",
                ["VerHist_430Desc"] = "Νέα: Ειδοποιήσεις-toast για σημαντικά συμβάντα (Γρήγορος Καθαρισμός, Αναφορά Μπαταρίας, Διαγνωστικό .zip), «AI-στυλ» βαθμολόγηση ασφάλειας διαγραφής ανά αρχείο (ηλικία + τύπος αρχείου, όχι πραγματικό ML) με ασφαλή Καταστροφέα Αρχείων (3 περάσματα τυχαίων δεδομένων - σημείωση: όχι εγγυημένο σε SSD/NVMe λόγω wear-leveling), βοηθός Αυτόματης Σύνδεσης (autologon) με ρητή προειδοποίηση αποθήκευσης κωδικού σε καθαρό κείμενο, δημοφιλείς συντομεύσεις λειτουργιών Windows, τεμπέλικη (lazy) φόρτωση καρτελών, εικονιδιοποιημένες λίστες με εικονική κύλιση (virtualization) για διεργασίες/υπηρεσίες/προγραμματισμένες εργασίες/κανόνες τείχους προστασίας, ομαλή κίνηση στις μπάρες προόδου, ανύψωση καρτών στο πέρασμα του ποντικιού, παλλόμενη κόκκινη κουκκίδα προσοχής υγείας όταν η βαθμολογία είναι χαμηλή, έξυπνη συχνότητα ανανέωσης όταν η εφαρμογή δεν είναι στο προσκήνιο. Διορθώθηκαν 2 πραγματικά bugs όπου η Εύρεση Μεγάλων Αρχείων/Διπλότυπων μπορούσε να καταρρεύσει σε απαγορευμένο φάκελο (π.χ. «Η μουσική μου»).",
                ["VerHist_410Title"] = "v4.1.0 - Νέο Όνομα, Γρήγορος Καθαρισμός & Έλεγχος Υγείας στυλ PC Manager",
                ["VerHist_410Desc"] = "Η εφαρμογή μετονομάστηκε σε «PC Performance & Maintenance Suite» (νομικός έλεγχος επιβεβαίωσε ότι το προηγούμενο όνομα παραβίαζε τον κανόνα ονομασίας της Microsoft). Νέα: Γρήγορος Καθαρισμός στην Αρχική (8 κατηγορίες πέρα από temp αρχεία, με κινούμενη σκούπα κατά τη σάρωση), Πλήρης Έλεγχος Υγείας σε δευτερεύον παράθυρο (στυλ PC Manager, με πραγματικά δεδομένα από κάθε σάρωση), καρφιτσωμένες συντομεύσεις tweaks στην Αρχική, sparkline ιστορικού απόδοσης σε κάθε πλακίδιο, εκτίμηση χρόνου καθυστέρησης εκκίνησης ανά εφαρμογή, εξαγωγή/εισαγωγή προφίλ tweaks, ειδικά εικονίδια SSD/NVMe στο πλακίδιο δίσκου, σημαίες στο μενού γλωσσών, screenshots στο README. Διορθώθηκε πραγματικό bug όπου ο Γρήγορος Καθαρισμός μπορούσε να «κολλήσει» σε απαγορευμένο φάκελο.",
                ["VerHist_400Title"] = "v4.0.0 - Προγραμματισμένη Συντήρηση, Boot Timeline, S.M.A.R.T. & Πολλά Ακόμα",
                ["VerHist_400Desc"] = "Νέα: Προγραμματισμένη εβδομαδιαία συντήρηση (Task Scheduler), Αυτόματο Gaming Mode, Χρονοδιάγραμμα Εκκίνησης, πραγματικό S.M.A.R.T. έλεγχος υγείας δίσκου με τάση στον χρόνο (διορθώθηκε bug όπου ήταν πάντα hardcoded «Healthy»), Προγραμματισμένες Εργασίες τρίτων, ιστορικό χρήσης μνήμης ανά διεργασία. Επίσης: Γρήγορη Εναλλαγή DNS, Ανίχνευση Δημόσιου Wi-Fi, Αναφορά Μπαταρίας, Διαγνωστική Αναφορά .zip, Μαζική εγκατάσταση εφαρμογών ανά κατηγορία, Διασταύρωση bloatware με εκκίνηση, Εξαγωγή «Η Συσκευή Μου», Σήμανση ξεπερασμένων drivers, νέα κάρτα «Τι έκανε πρόσφατα η εφαρμογή», αναζήτηση στις Επιπλέον Ρυθμίσεις, ReadyToRun για ταχύτερη εκκίνηση. Πλήρης έλεγχος γραμμής κατάστασης/μπαρών προόδου σε όλη την εφαρμογή, CONTRIBUTING.md/CHANGELOG.md.",
                ["VerHist_370Title"] = "v3.7.0 - Διανυσματικά Εικονίδια & Διορθώσεις Οπτικών",
                ["VerHist_370Desc"] = "Όλα τα emoji της εφαρμογής (τίτλοι καρτών, καρτέλες, πλευρικό μενού, οδηγός χρήσης) αντικαταστάθηκαν με νέα διανυσματικά εικονίδια που ακολουθούν σωστά κάθε θέμα/mode. Διορθώθηκε το κινούμενο φόντο «Τροχιές» (ελλειπτικό, υπό γωνία, πλέον περιορισμένο ακριβώς στη λωρίδα καρτελών). Διορθώθηκε λάθος «C::» στους δίσκους αποθήκευσης. Νέα επικεφαλίδα «Πληροφορίες Συστήματος».",
                ["VerHist_360Title"] = "v3.6.0 - Ελαφρύτερη Εφαρμογή, Ελαφρύτερα Windows & Οπτικές Προσθήκες",
                ["VerHist_360Desc"] = "Νέο πλαίσιο «Ελαφρύτερα Windows» στις Επιπλέον Ρυθμίσεις (απενεργοποίηση Εφαρμογών Παρασκηνίου, SysMain/Superfetch, Επιλογές Ευρετηρίασης, Προφίλ Χαμηλής Χρήσης Πόρων). Η «Η Συσκευή Μου» πλέον χρησιμοποιεί cache για στοιχεία που δεν αλλάζουν σε μια συνεδρία. Το κινούμενο φόντο παύει και όταν το παράθυρο γίνεται αόρατο, όχι μόνο σε ελαχιστοποίηση. Ομαλή μετάβαση καρτελών, κόκκινη ένδειξη προσοχής στην καρτέλα Υγεία όταν η βαθμολογία είναι χαμηλή, και σύγκριση ελεύθερου χώρου πριν/μετά τον καθαρισμό cache browser. Σημείωση ειλικρίνειας: η έγχρωμη απόδοση των εικονιδίων του οδηγού χρήσης δοκιμάστηκε με δύο διαφορετικές διορθώσεις γραμματοσειράς, καμία δεν επαρκεί πλήρως σε αυτό το περιβάλλον - παραμένει ανοιχτό, χρειάζεται πραγματικά διανυσματικά εικονίδια.",
                ["VerHist_351Title"] = "v3.5.1 - Οπτικές Διορθώσεις: Κενό Τίτλου, Θέμα Εφαρμογής, Θερμόμετρα",
                ["VerHist_351Desc"] = "Μεγαλύτερο κενό ανάμεσα στη λωρίδα καρτελών και τον τίτλο, με περισσότερο ορατό κινούμενο φόντο. Διορθώθηκε πραγματικό bug που έκανε το ComboBox «Θέμα Εφαρμογής» να εμφανίζεται ανοιχτόχρωμο σε ΟΛΑ τα θέματα (dark και light) αντί για το πραγματικό θεματικό χρώμα - επιβεβαιωμένο με ζωντανή μέτρηση pixel. Τα εικονίδια θερμοκρασίας (🌡) αντικαταστάθηκαν με διανυσματικά εικονίδια, σωστά χρωματισμένα σε κάθε έκδοση Windows.",
                ["VerHist_350Title"] = "v3.5.0 - Τέσσερα Γνωστά Κενά Διορθώθηκαν",
                ["VerHist_350Desc"] = "Οι διακόπτες στις Επιπλέον Ρυθμίσεις δείχνουν πλέον την πραγματική τρέχουσα κατάσταση του μητρώου (επιβεβαιωμένο ζωντανά) αντί να ξεκινούν πάντα ανενεργοί. Το σημείο επαναφοράς πριν από εγκατάσταση οδηγού (Microsoft Update Catalog) είναι πλέον αυτόματο, όχι ξεχωριστή ερώτηση. Διορθώθηκε πραγματικό bug στην ανίχνευση του Windows Defender στο «Η Συσκευή Μου» (λάθος όνομα κλάσης WMI). Η καρτέλα «Skins» πλέον περνά από το σύστημα μετάφρασης.",
                ["VerHist_344Title"] = "v3.4.4 - Διόρθωση Εντοπισμού Ενημέρωσης στον Installer",
                ["VerHist_344Desc"] = "Το μήνυμα «εντοπίστηκε ήδη εγκατεστημένη έκδοση» στην αρχική σελίδα του installer δεν εμφανιζόταν ποτέ λόγω λάθος μορφοποίησης της διαδρομής μητρώου - διορθώθηκε, επιβεβαιωμένο ότι το κλειδί μητρώου διαβάζεται σωστά.",
                ["VerHist_343Title"] = "v3.4.3 - Διόρθωση Κρασαρίσματος στο Πρώτο Άνοιγμα",
                ["VerHist_343Desc"] = "Σε ορισμένες περιπτώσεις, το κλείσιμο του οδηγού χρήσης στο πρώτο άνοιγμα της εφαρμογής (Παράλειψη/Ξεκινήστε) προκαλούσε σφάλμα «Cannot set Owner property» επειδή ήταν στιγμιαία το μοναδικό ανοιχτό παράθυρο - διορθώθηκε, επιβεβαιωμένο ζωντανά.",
                ["VerHist_342Title"] = "v3.4.2 - Έξυπνη Ενημέρωση & Πλουσιότερος Οδηγός Χρήσης",
                ["VerHist_342Desc"] = "Ο installer πλέον αναγνωρίζει ήδη εγκατεστημένη έκδοση και αντιγράφει ΜΟΝΟ τα αρχεία που πραγματικά άλλαξαν αντί για ολόκληρη την εφαρμογή, με σχετικό μήνυμα στην αρχική σελίδα. Ο οδηγός χρήσης πρώτης εκκίνησης ξαναγράφτηκε ώστε κάθε σελίδα να εξηγεί συγκεκριμένες λειτουργίες και πώς να τις χρησιμοποιήσετε (ποια κουμπιά να πατήσετε), όχι μόνο μια γενική περιγραφή της κάθε καρτέλας.",
                ["VerHist_341Title"] = "v3.4.1 - Διόρθωση Ορατότητας Κουμπιού Οδηγού",
                ["VerHist_341Desc"] = "Το κουμπί «Προβολή Οδηγού Χρήσης» στη Βοήθεια είχε πολύ χαμηλή αντίθεση σε ορισμένα θέματα και έμοιαζε με απλό κείμενο αντί για κουμπί - τώρα εμφανίζεται με συμπαγές χρώμα έμφασης, ευδιάκριτο σε όλα τα θέματα.",
                ["VerHist_340Title"] = "v3.4.0 - Οδηγός Χρήσης Πρώτης Εκκίνησης & Ασφαλής Απεγκατάσταση",
                ["VerHist_340Desc"] = "Νέος εικονογραφημένος οδηγός χρήσης εμφανίζεται στο πρώτο άνοιγμα της εφαρμογής (10 σελίδες, μία ανά καρτέλα), με δυνατότητα επανάληψης όποτε θέλετε από τη Βοήθεια. Ο installer ρωτάει πλέον κατά την απεγκατάσταση αν θέλετε να επαναφερθούν όλες οι ρυθμίσεις των Windows που άλλαξε η εφαρμογή στις πραγματικές προηγούμενες τιμές τους, και προστέθηκε σελίδα περιγραφής της εφαρμογής στον οδηγό εγκατάστασης.",
                ["VerHist_330Title"] = "v3.3.0 - Η Συσκευή Μου & Ακριβέστερη Ανίχνευση Δίσκων",
                ["VerHist_330Desc"] = "Νέο section «Η Συσκευή Μου» στην κορυφή της καρτέλας Σύστημα - 8 κάρτες με πλήρη ανάλυση hardware/λειτουργικού (Μητρική, Δίσκοι, Λειτουργικό, Δίκτυο, CPU, Μπαταρία, RAM, GPU), καθαρά πληροφοριακό, χωρίς κουμπιά. Διορθώθηκε bug που έκανε την ανίχνευση τύπου δίσκου (NVMe/SATA/USB) να αποτυγχάνει σε συγκεκριμένους δίσκους λόγω περιορισμού του Storage WMI provider - αντικαταστάθηκε με αξιόπιστη, επιβεβαιωμένη μέθοδο. Προστέθηκε επίσης σωστή μέτρηση τοπικών διαχειριστών.",
                ["VerHist_321Title"] = "v3.2.1 - Κατάσταση Δικτύου στην Αρχική",
                ["VerHist_321Desc"] = "Νέος δείκτης κατάστασης σύνδεσης (🟢 Συνδεδεμένο / 🔴 Χωρίς Internet, με latency σε ms) στην Αρχική, μαζί με ζωντανό γράφημα κίνησης δικτύου (όπως στη Διαχείριση Εργασιών) και κουμπί άμεσης μετάβασης στο Δίκτυο & Ασφάλεια.",
                ["VerHist_320Title"] = "v3.2.0 - Αποκλεισμός Τηλεμετρίας, Cloud Cleanup & Ελευθέρωση Μνήμης",
                ["VerHist_320Desc"] = "Νέα κάρτα «Απόρρητο & Προστασία» στο Δίκτυο & Ασφάλεια, με αποκλεισμό γνωστών endpoints τηλεμετρίας Microsoft (hosts file, αναστρέψιμο). Νέα εργαλεία εύρεσης μεγάλων αρχείων στα τοπικά Google Drive/Dropbox (όταν εντοπίζονται). Νέο κουμπί «Ελευθέρωση Μνήμης» στη Σύστημα - ελευθερώνει αδρανή μνήμη εφαρμογών παρασκηνίου χωρίς να τις κλείνει.",
                ["VerHist_311Title"] = "v3.1.1 - Ελαφρύτερη εφαρμογή, καθαρότερο κινούμενο φόντο",
                ["VerHist_311Desc"] = "Το κινούμενο φόντο περιορίστηκε στην περιοχή τίτλου/καρτελών (δεν κρύβεται πια πίσω από τις κάρτες περιεχομένου) και αφαιρέθηκε εντελώς από τα δευτερεύοντα παράθυρα (Βοήθεια, Ιστορικό, Ρυθμίσεις Εμφάνισης, κ.ά.). Σταματά αυτόματα όποτε η εφαρμογή είναι ελαχιστοποιημένη ή χωρίς focus - η κατανάλωση CPU σε αδράνεια μειώθηκε κατά ~80%. Αυξήθηκε η αντίθεση σε αρκετά στυλ φόντου (Γρανάζια, Τροχιές, Κύματα, κ.ά.) που ήταν πολύ αχνά, ειδικά σε Light mode. Διορθώθηκε η ελληνική σημαία στην επιλογή γλώσσας (έδειχνε λάθος σχέδιο).",
                ["VerHist_310Title"] = "v3.1.0 - Πλήρης μετάφραση, διορθώσεις εμφάνισης & θερμοκρασιών",
                ["VerHist_310Desc"] = "Ολόκληρη η εφαρμογή είναι πλέον μεταφρασμένη σε 4 γλώσσες (Ελληνικά/Αγγλικά/Γερμανικά/Γαλλικά), συμπεριλαμβανομένων όλων των μηνυμάτων κατάστασης/επιβεβαίωσης/σφάλματος και κάθε δευτερεύοντος παραθύρου. Η ενημέρωση οδηγών μέσω SDIO δεν κατεβάζει/εγκαθιστά πλέον αυτόματα - μόνο σάρωση. Προστέθηκαν πραγματικά εικονίδια GPU/Δίσκου στην Αρχική και μεγαλύτερα εικονίδια σε όλα τα πλακίδια υλικού. Το κινούμενο γρανάζι του τίτλου αναπαράγει πλέον ακριβώς τη διάταξη της 2.8.2, με μεγαλύτερα, πιο ευδιάκριτα δόντια. Διορθώθηκαν: ψευδής ένδειξη 0°C στη θερμοκρασία CPU (δείχνει πλέον σωστά το 🔒 όταν το VBS μπλοκάρει την πρόσβαση), ασυμβίβαστη αντίθεση γραμμής κατάστασης σε 3 θέματα, ασχημάτιστο dropdown στη δοκιμή δίσκου, κολλημένα κουμπιά στα Εργαλεία Υγείας, λείπον εικονίδιο VLC, λανθασμένο αναγνωριστικό winget του Viber, και το κουμπί ανανέωσης στις Πρόσθετες Λειτουργίες Windows που δεν έδειχνε σφάλμα σε αποτυχία σάρωσης. Το πλευρικό μενού πλέον προσαρμόζεται στο πραγματικό του μέγεθος αντί να τεντώνεται, και το παράθυρο της εφαρμογής είναι πιο συμπαγές.",
                ["VerHist_300Title"] = "v3.0.0 - Νέα έκδοση: πλήρης μεταφορά σε WPF",
                ["VerHist_300Desc"] = "Η εφαρμογή ξαναχτίστηκε από την αρχή σε σύγχρονη τεχνολογία (.NET 8/WPF, αντί για WinForms) - πιο γρήγορη, πιο ομαλή, με πραγματική αλλαγή μεγέθους παραθύρου. Όλες οι 8 καρτέλες είναι πλήρως λειτουργικές. Η Ενημέρωση Οδηγών έγινε πολυπηγαία σε ΜΙΑ ενιαία λίστα: Windows Update, Microsoft Update Catalog, AMD/NVIDIA (επίσημες σελίδες), Dell Command Update και Snappy Driver Installer (πάντα αθόρυβα, χωρίς δικό τους παράθυρο) - με σήμανση '✓✓ Επιβεβαιωμένο' όταν συμφωνούν δύο ανεξάρτητες πηγές. Προστέθηκαν πραγματικά λογότυπα εφαρμογών (λήψη μία φορά, τοπική αποθήκευση), ομαδοποιημένη λίστα προτεινόμενων εφαρμογών, ενοποιημένη λίστα πρόσθετων λειτουργιών Windows, πλήρες πλαίσιο διακοπτών Win11 στο ViVeTool, νέο παράθυρο Ρυθμίσεων Εμφάνισης με ζωντανή προεπισκόπηση, και δεκάδες διορθώσεις εμφάνισης/σταθερότητας.",
                ["VerHist_278Title"] = "2.7 – 2.8.2 · Πραγματική αλλαγή μεγέθους & τελική στίλβωση",
                ["VerHist_278Desc"] = "Το παράθυρο απέκτησε πραγματική δυνατότητα αλλαγής μεγέθους/μεγιστοποίησης, με αναλογική κλιμάκωση περιεχομένου. Θεματοποιήθηκαν πλήρως οι γραμμές κύλισης, μεγάλωσε η γραμμή κατάστασης, προστέθηκε η «Διαχείριση UWP Εφαρμογών» και διορθώθηκε η ψευδής ένδειξη «εκκρεμεί επανεκκίνηση» στη Βαθμολογία Υγείας.",
                ["VerHist_26Title"] = "2.1 – 2.6 · Ενσωματωμένο μενού & πολυπηγαία ενημέρωση οδηγών",
                ["VerHist_26Desc"] = "Το πλευρικό μενού έγινε πραγματικά ενσωματωμένο στο κύριο παράθυρο. Η σάρωση οδηγών επεκτάθηκε σε πολλαπλές επίσημες πηγές (Windows Update, AMD, NVIDIA, Dell) με σήμανση «Επιβεβαιωμένο» όταν συμφωνούν δύο πηγές. Προστέθηκε αναγνώριση υπολογιστών Lenovo/HP, διακριτικές ειδοποιήσεις toast και το θέμα εμφάνισης «Microsoft PC Manager».",
                ["VerHist_20Title"] = "2.0 · Νέα καρτέλα Αρχική & πλήθος εργαλείων",
                ["VerHist_20Desc"] = "Προστέθηκε η καρτέλα «Αρχική» με μετρητές CPU/Μνήμης/Δίσκου, Βαθμολογία Υγείας Συστήματος με αυτόματη διόρθωση, Ανάλυση Χώρου Δίσκου ανά κατηγορία, Γρήγορη Σάρωση Defender και Καθαρισμός Cache Περιηγητών. Προστέθηκαν επίσης πλήρης λίστα Λειτουργιών Windows, Βαθιά Απεγκατάσταση, Διαχείριση Συσκευών-Φαντασμάτων, Προσαρμοσμένες Επιλογές Δεξιού Κλικ και Επεξεργαστής αρχείου Hosts.",
                ["VerHist_19Title"] = "1.8 – 1.9 · Οδηγοί, Υγεία & Ασφάλεια",
                ["VerHist_19Desc"] = "Προστέθηκε η πρώτη Ενημέρωση Οδηγών Συσκευών (Windows Update), νέοι έλεγχοι υγείας συστήματος και ενότητα «AI & Copilot». Ακολούθησαν Σημεία Επαναφοράς Συστήματος, Διαχείριση Κανόνων Firewall, καθολική αναζήτηση, βελτιστοποίηση Υπηρεσιών, Ιστορικό Ενεργειών, αντίγραφα ασφαλείας οδηγών και ασφαλής Καθαρισμός Μητρώου.",
                ["VerHist_17Title"] = "1.7 · Σταθεροποίηση & οργάνωση",
                ["VerHist_17Desc"] = "Οι Προτεινόμενες Εφαρμογές οργανώθηκαν σε 7 σαφείς κατηγορίες, τα κουμπιά απέκτησαν πλουσιότερα θεματικά εφέ και νέους διακόπτες στυλ Windows 11. Ολοκληρώθηκε η μετάφραση όλου του Ιστορικού Εκδόσεων στις 4 γλώσσες.",
                ["VerHist_16Title"] = "1.6 · Θέματα και κινούμενα φόντα",
                ["VerHist_16Desc"] = "Τα θέματα εμφάνισης απέκτησαν αυθεντικό ύφος εποχής (Windows 98, Vista/Aero, Nordic/Solarized) και επιλέξιμα κινούμενα φόντα (Γρανάζια, Τροχιές, Σωματίδια). Οι Ρυθμίσεις Εμφάνισης αναδιοργανώθηκαν σε καρτέλες με ζωντανή προεπισκόπηση.",
                ["VerHist_15Title"] = "1.4 – 1.5 · Σύγχρονο μενού και πρώτες μεταφράσεις",
                ["VerHist_15Desc"] = "Προστέθηκαν το Ιστορικό Εκδόσεων, ένα νέο προαιρετικό σύγχρονο μενού (πλευρικό ή οριζόντιο) και η κατηγορία Προτεινόμενων Εφαρμογών (K-Lite, 7-Zip, VLC, PowerToys κ.ά.). Ξεκίνησε η υποστήριξη Αγγλικών/Γαλλικών/Γερμανικών.",
                ["VerHist_13Title"] = "1.0 – 1.3 · Τα θεμέλια",
                ["VerHist_13Desc"] = "Η εφαρμογή ξεκίνησε ως ένα απλό παράθυρο χωρίς καρτέλες, με βασικό σκούρο θέμα. Απέκτησε τη δομή καρτελών (Βελτιστοποίηση, Υγεία, Δίκτυο, Εργαλεία), αυτόματη ανύψωση δικαιωμάτων Διαχειριστή, τα πρώτα θέματα εμφάνισης (light/dark) και διανυσματικά εικονίδια. Προστέθηκαν το ViVeTool για πειραματικές λειτουργίες Windows, το πακέτο codecs K-Lite, η ασφαλής απεγκατάσταση εφαρμογών Metro/UWP και υποστήριξη οθονών υψηλής ανάλυσης.",
                ["Help_Title"] = "Οδηγίες & Πληροφορίες",
                ["Help_InstructionsTab"] = "Οδηγίες",
                ["Help_Shortcuts"] = "Ctrl+1 έως Ctrl+8: γρήγορη εναλλαγή καρτέλας. Ctrl+M: εμφάνιση/απόκρυψη κλασικού μενού. Ctrl+F: εστίαση στο πεδίο αναζήτησης. Ctrl+H: άνοιγμα Πλήρους Ελέγχου Υγείας. Το πεδίο αναζήτησης στην κορυφή δείχνει ζωντανά αποτελέσματα από όλες τις καρτέλες/εργαλεία/ρυθμίσεις καθώς πληκτρολογείτε.",
                ["Help_HomeTitle"] = "Αρχική",
                ["Help_HomeDesc"] = "Μετρητές CPU/RAM/Δίσκου/Θερμοκρασιών σε πραγματικό χρόνο (οι θερμοκρασίες εμφανίζονται μόνο αν το Memory Integrity/VBS δεν εμποδίζει απευθείας πρόσβαση στο υλικό - 🔒 αντί για τιμή σημαίνει αυτό). Βαθμολογία Υγείας Συστήματος με αυτόματη διόρθωση ευρημάτων. Ανάλυση Χώρου Δίσκου ανά κατηγορία με drill-down.",
                // ΝΕΟ - ρητό αίτημα χρήστη: "ο οδηγός χρήσης με εικονίδια GIF με αναλυτική επεξήγηση
                // κάθε λειτουργίας και κουμπιού ανά καρτέλα" - μία νέα, αναλυτική περιγραφή ανά κάρτα
                // (όχι πια μόνο μία συνοπτική παράγραφο ανά ΚΑΡΤΕΛΑ) - βλ. HelpWindow.xaml για τη νέα
                // δομή (εικονίδιο ανά κάρτα + τίτλος + αυτό εδώ το κείμενο), ένα κλειδί ανά κάρτα.
                ["Help_Home_Monitoring"] = "Οι μπάρες CPU/RAM/GPU/Δίσκου ενημερώνονται κάθε 1 δευτερόλεπτο. Τα βελάκια ‹ › στο πλακίδιο δίσκου εναλλάσσουν ανάμεσα σε όλους τους συνδεδεμένους δίσκους σας.",
                ["Help_Home_NetworkStatusTitle"] = "Κατάσταση Δικτύου",
                ["Help_Home_NetworkStatus"] = "Η πράσινη/κόκκινη κουκκίδα δείχνει αν υπάρχει πραγματική σύνδεση Internet (ping, όχι μόνο τοπικό καλώδιο/Wi-Fi), με γράφημα κίνησης σε πραγματικό χρόνο δίπλα. Το κουμπί «Δίκτυο & Ασφάλεια» μεταφέρει απευθείας στην αντίστοιχη καρτέλα.",
                ["Help_Home_HealthScore"] = "Βαθμολογία 0-100 με λίστα ευρημάτων. «Διόρθωση Όλων» διορθώνει αυτόματα ΜΟΝΟ τα ευρήματα χώρου (καθαρισμός %TEMP%) - τα ευρήματα Windows Defender εμφανίζονται μόνο, ποτέ δεν αλλάζονται αυτόματα. «Ανανέωση» ξαναϋπολογίζει τη βαθμολογία. «Πλήρης Έλεγχος Υγείας» ανοίγει το γραφικό, βήμα-προς-βήμα εργαλείο (στυλ PC Manager) σε δικό του παράθυρο - καλύπτει και τον γρήγορο καθαρισμό χώρου/cache περιηγητών, registry, ρυθμίσεις, εφαρμογές και δίκτυο σε ένα ενιαίο σημείο.",
                ["Help_Home_Pinned"] = "Εμφανίζει τα tweaks που έχετε καρφιτσώσει (★) από τις Επιπλέον Ρυθμίσεις, με απευθείας διακόπτη ενεργοποίησης/απενεργοποίησης χωρίς αλλαγή καρτέλας.",
                ["Help_Home_DiskAnalysis"] = "Το «Ανάλυση» χτίζει μία έγχρωμη μπάρα με το πραγματικό μέγεθος κάθε κατηγορίας (Παιχνίδια/Εφαρμογές/Φωτογραφίες/Βίντεο/Έγγραφα/Λήψεις/Windows/Άλλα). Κλικ σε segment ή στοιχείο του υπομνήματος ανοίγει λεπτομερή ανάλυση φακέλων (εκτός από «Άλλα»).",
                ["Help_Home_RecentActivity"] = "Δείχνει τις 3 πιο πρόσφατες ενέργειες της εφαρμογής σε πραγματικό χρόνο. Το «Δείτε Όλα» ανοίγει το πλήρες Ιστορικό Ενεργειών σε δικό του παράθυρο.",
                ["Help_OptTitle"] = "Βελτιστοποίηση",
                ["Help_OptDesc"] = "Office Mode / Gaming Mode (προφίλ ενέργειας + ρυθμίσεις). Ενημέρωση Οδηγών πολλαπλών πηγών σε ΜΙΑ λίστα - Windows Update, Microsoft Update Catalog, επίσημες σελίδες AMD/NVIDIA, Dell Command Update, Snappy Driver Installer (πάντα αθόρυβα) και ανίχνευση Lenovo - με ένδειξη «✓✓ Επιβεβαιωμένο» όταν συμφωνούν δύο ανεξάρτητες πηγές. Αντίγραφο ασφαλείας/επαναφορά οδηγών, καθαρισμός αποθήκης οδηγών, και ο Διαχειριστής Ενημερώσεων Λογισμικού (winget + Microsoft Store).",
                ["Help_Opt_OfficeMode"] = "Ο διακόπτης εφαρμόζει προφίλ ενέργειας+ρυθμίσεις βελτιστοποιημένο για εργασία γραφείου. Αμοιβαία αποκλειόμενο με το Gaming Mode - η ενεργοποίηση του ενός απενεργοποιεί αυτόματα το άλλο. Η απενεργοποίηση επανεκκινεί σύντομα την Εξερεύνηση (μικρό τρεμόπαιγμα desktop, φυσιολογικό).",
                ["Help_Opt_GamingMode"] = "Ίδιο μοτίβο με το Office Mode, αντίστροφα - προφίλ βελτιστοποιημένο για gaming. Αμοιβαία αποκλειόμενο με το Office Mode.",
                ["Help_Opt_Drivers"] = "Το κυκλικό κουμπί σάρωσης ελέγχει διαδοχικά AMD/NVIDIA (επίσημες σελίδες), Windows Update, ΚΑΙ Microsoft Update Catalog (κατά Hardware ID) - όλα σε ΜΙΑ λίστα. Το κουμπί ενέργειας ανά αποτέλεσμα διαφέρει: AMD/NVIDIA ανοίγουν τη σελίδα λήψης (καμία αυτόματη εγκατάσταση), Windows Update εγκαθιστά στο παρασκήνιο, Catalog δημιουργεί ΠΡΩΤΑ αυτόματο σημείο επαναφοράς πριν εγκαταστήσει. Αν εντοπιστεί Dell/SDIO, εμφανίζονται επιπλέον κουμπιά για το επίσημο εργαλείο τους.",
                ["Help_Opt_DriverBackup"] = "«Δημιουργία Αντιγράφου» αποθηκεύει όλους τους τρέχοντες οδηγούς σε φάκελο της επιλογής σας (DISM export). «Επαναφορά» τους εγκαθιστά ξανά από αντίγραφο (pnputil), μετά από επιβεβαίωση.",
                ["Help_Opt_DriverStore"] = "Το «Σάρωση» ομαδοποιεί τους οδηγούς της Αποθήκης Οδηγών κατά αρχείο και επισημαίνει ως διαγράψιμα ΜΟΝΟ τα παλιότερα αντίγραφα κάθε ομάδας - το νεότερο κρατιέται πάντα. «Διαγραφή» ανά γραμμή αφαιρεί το συγκεκριμένο διπλότυπο πακέτο (pnputil delete-driver).",
                ["Help_Opt_SoftwareUpdate"] = "«Σάρωση» τρέχει «winget upgrade» για όλες τις εγκατεστημένες εφαρμογές. Επιλέξτε γραμμές (ή «Επιλογή Όλων») και πατήστε «Ενημέρωση Επιλεγμένων». Το «Έλεγχος μέσω Microsoft Store» συμπληρώνει το winget για ενημερώσεις εφαρμογών Store/UWP που μπορεί να μην πιάσει.",
                ["Help_Opt_ScheduledMaintenance"] = "Ο διακόπτης δημιουργεί/αφαιρεί ΠΡΑΓΜΑΤΙΚΗ εβδομαδιαία εργασία στον Windows Task Scheduler (όχι εσωτερικό timer της εφαρμογής) - η συντήρηση τρέχει ακόμα κι αν η εφαρμογή είναι κλειστή.",
                ["Help_Opt_AutoGamingMode"] = "Ο διακόπτης παρακολουθεί για πλήρη οθόνη/παιχνίδι σε εξέλιξη και εφαρμόζει/αναιρεί αυτόματα το Gaming Mode ανάλογα - καμία χειροκίνητη ενέργεια χρειάζεται μετά την ενεργοποίηση.",
                ["Help_HealthTitle"] = "Υγεία & Συντήρηση",
                ["Help_HealthDesc"] = "SFC, DISM (Check/RestoreHealth), CHKDSK, ReTrim SSD, επιδιόρθωση κατεστραμμένων συντομεύσεων, καθαρισμός WinSxS, έλεγχος έκδοσης .NET Framework. Καθαρισμός Μητρώου (στενός σκοπός - μόνο ελλείποντες uninstallers/obsolete MuiCache, με αυτόματο αντίγραφο .reg). Καθαρισμός Cache 6 Περιηγητών (Chrome/Edge/Brave/Opera/Vivaldi/Firefox). Έλεγχος υγείας WinRE.",
                ["Help_Health_DiskTrend"] = "Ιστορικό στιγμιότυπων S.M.A.R.T. ανά δίσκο, καταγράφεται αυτόματα όταν επισκέπτεστε την καρτέλα Σύστημα - καθαρά πληροφοριακό, καμία ενέργεια εδώ.",
                ["Help_Health_Tools"] = "8 ανεξάρτητα εργαλεία: SFC (έλεγχος αρχείων συστήματος), DISM CheckHealth, DISM RestoreHealth (επιδιόρθωση component store - ζητά επιβεβαίωση), CHKDSK (έλεγχος δίσκου - ζητά επιβεβαίωση), ReTrim SSD, Επιδιόρθωση Συντομεύσεων (σπασμένα .lnk), Καθαρισμός WinSxS (DISM StartComponentCleanup), και Έλεγχος Έκδοσης .NET Framework (μόνο πληροφορία, καμία αλλαγή).",
                ["Help_Health_RegistryCleaner"] = "Σκόπιμα στενός σκοπός - ΜΟΝΟ ελλείποντες καταχωρήσεις απεγκατάστασης και ξεπερασμένο MuiCache, ΟΧΙ γενικός καθαρισμός μητρώου. «Σάρωση» εντοπίζει ευρήματα, επιλέξτε όσα θέλετε (checkbox ανά γραμμή) και πατήστε «Διαγραφή Επιλεγμένων» - δημιουργείται αυτόματο αντίγραφο ασφαλείας πριν τη διαγραφή.",
                ["Help_Health_BrowserCache"] = "Ένα κουμπί ανά ανιχνευμένο browser (Chrome/Edge/Brave/Opera/Vivaldi/Firefox) - κλικ καθαρίζει το cache ΜΟΝΟ αυτού του browser και δείχνει τον χώρο που ελευθερώθηκε.",
                ["Help_Health_WinRE"] = "Δείχνει αν το Windows Recovery Environment είναι ενεργό (πράσινο) ή απενεργοποιημένο (κόκκινο). «Ανανέωση Κατάστασης» ξαναελέγχει. «Ενεργοποίηση WinRE» το επανενεργοποιεί αν είναι απενεργοποιημένο, μετά από επιβεβαίωση.",
                ["Help_Health_BatteryReport"] = "Δημιουργεί την επίσημη αναφορά μπαταρίας των Windows (powercfg /batteryreport) και την ανοίγει αυτόματα στον browser σας.",
                ["Help_Health_DiagnosticsZip"] = "Συγκεντρώνει systeminfo, Event Log και το Ιστορικό Ενεργειών της εφαρμογής σε ΕΝΑ αρχείο .zip - χρήσιμο για να το μοιραστείτε όταν ζητάτε βοήθεια για κάποιο πρόβλημα.",
                ["Help_NetworkTitle"] = "Δίκτυο & Ασφάλεια",
                ["Help_NetworkDesc"] = "Windows Defender - Γρήγορη Σάρωση. Πλήρης Επαναφορά Δικτύου/Winsock, πληροφορίες δικτύου, επανεκκίνηση Wi-Fi, πίνακας δρομολόγησης. Διαχείριση Κανόνων Firewall (αναζήτηση+toggle ανά κανόνα), Εργαλεία Πολιτικής Firewall (εξαγωγή/εισαγωγή .wfw, επαναφορά προεπιλογών), Επεξεργαστής αρχείου Hosts.",
                ["Help_Net_TrafficPerApp"] = "Το «Έναρξη» ξεκινά καταγραφή συμβάντων πυρήνα (ETW) για να δείξει ποια εφαρμογή καταναλώνει εύρος ζώνης ΤΩΡΑ, ανανεώνεται κάθε 1s. Απαιτεί δικαιώματα Διαχειριστή (η εφαρμογή τα έχει ήδη) - αν κάποιο άλλο εργαλείο χρησιμοποιεί ήδη τον ίδιο μηχανισμό, η Έναρξη θα το διακόψει. «Διακοπή» σταματά την παρακολούθηση.",
                ["Help_Net_QuickActionsTitle"] = "Γρήγορες Ενέργειες",
                ["Help_Net_QuickActions"] = "«Πλήρης Επαναφορά Δικτύου» επαναφέρει winsock/IP stack. «Πληροφορίες Δικτύου» δείχνει ipconfig /all. «Επανεκκίνηση Wi-Fi» επανεκκινεί τους προσαρμογείς (ζητά επιβεβαίωση - χάνεται προσωρινά η σύνδεση). «Διαχείριση Windows Firewall» ανοίγει τον επίσημο Πίνακα Ελέγχου. «Πίνακας Δρομολόγησης» δείχνει route print.",
                ["Help_Net_Privacy"] = "«Γρήγορη Σάρωση» ξεκινά σάρωση του Windows Defender στο Windows Security app. Το κουμπί Αποκλεισμού Τηλεμετρίας εναλλάσσεται (Αποκλεισμός/Άρση Αποκλεισμού) ανάλογα με την πραγματική τρέχουσα κατάσταση του hosts file - μπλοκάρει γνωστά endpoints τηλεμετρίας Microsoft, μετά από επιβεβαίωση.",
                ["Help_Net_FirewallRules"] = "Το πλαίσιο αναζήτησης φιλτράρει (έως 50 αποτελέσματα ταυτόχρονα). «Φόρτωση Κανόνων» διαβάζει όλους τους κανόνες Firewall (μπορεί να είναι εκατοντάδες). Κάθε κανόνας έχει δικό του διακόπτη ενεργοποίησης/απενεργοποίησης.",
                ["Help_Net_FirewallPolicy"] = "«Εξαγωγή Πολιτικής» αποθηκεύει όλες τις ρυθμίσεις Firewall σε αρχείο .wfw. «Εισαγωγή Πολιτικής» τις επαναφέρει από αρχείο, μετά από επιβεβαίωση. «Επαναφορά Προεπιλογών» (κόκκινο) επαναφέρει το Firewall στις εργοστασιακές ρυθμίσεις των Windows - ανεπίστρεπτη ενέργεια, ζητά έντονη προειδοποίηση.",
                ["Help_Net_QuickDns"] = "Ένα κλικ εφαρμόζει τον επιλεγμένο DNS πάροχο (Cloudflare/Google/Quad9) σε ΚΑΘΕ ενεργό προσαρμογέα δικτύου - καμία χειροκίνητη εισαγωγή IP. «Επαναφορά (DHCP)» επαναφέρει αυτόματο DNS από τον router σας.",
                ["Help_Net_HostsEditor"] = "Επεξεργαστείτε απευθείας το αρχείο hosts μέσα στο πλαίσιο κειμένου. «Φόρτωση» το ξαναδιαβάζει από τον δίσκο. «Αποθήκευση» γράφει τις αλλαγές (με αυτόματο αντίγραφο ασφαλείας πριν), μετά από επιβεβαίωση. «Επαναφορά Προεπιλογών» γεμίζει το πλαίσιο με το προεπιλεγμένο περιεχόμενο των Windows (δεν αποθηκεύεται μέχρι να πατήσετε Αποθήκευση). «Άνοιγμα με Σημειωματάριο» ανοίγει το πραγματικό αρχείο σε Notepad.",
                ["Help_TweaksTitle"] = "Επιπλέον Ρυθμίσεις",
                ["Help_TweaksDesc"] = "Δεκάδες registry tweaks με backup/restore, ενότητες AI & Copilot και Απόδοση (HAGS/Battery/USB/PCIe). Κρυπτογράφηση Συσκευής (άνοιγμα επίσημων Ρυθμίσεων). Επιλογές Δεξιού Κλικ - ενσωματωμένες (Ιδιοκτησία/PowerShell Εδώ) ΚΑΙ πλήρης εργαλείο δημιουργίας προσαρμοσμένων επιλογών μενού. Προεπιλογές Οπτικών Εφέ (Καλύτερη Εμφάνιση/Απόδοση/Ισορροπημένο).",
                ["Help_Tweaks_ProfileTitle"] = "Προφίλ Ρυθμίσεων",
                ["Help_Tweaks_Profile"] = "«Εξαγωγή Προφίλ» αποθηκεύει την ON/OFF κατάσταση ΟΛΩΝ των tweaks σε αρχείο .json. «Εισαγωγή Προφίλ» εφαρμόζει ξανά ένα αποθηκευμένο προφίλ σε άλλο (ή στο ίδιο) υπολογιστή, μετά από επιβεβαίωση - χρήσιμο για να ρυθμίσετε πολλά μηχανήματα με τις ίδιες προτιμήσεις γρήγορα.",
                ["Help_Tweaks_Rows"] = "Κάθε γραμμή tweak (στις κατηγορίες Κύριες Ρυθμίσεις, AI & Copilot, Απόδοση, Ελαφρύτερα Windows) έχει έναν διακόπτη ενεργοποίησης/απενεργοποίησης που εφαρμόζει την πραγματική αλλαγή μητρώου/συστήματος αμέσως, ΚΑΙ ένα κουμπί ★ που την καρφιτσώνει στην Αρχική για γρήγορη πρόσβαση χωρίς αλλαγή καρτέλας. Το πλαίσιο αναζήτησης στην κορυφή φιλτράρει και τις 4 λίστες ταυτόχρονα.",
                ["Help_Tweaks_LighterWindows"] = "Ίδιο μοτίβο διακόπτη+καρφίτσωμα με τα υπόλοιπα tweaks. «Άνοιγμα Επιλογών Ευρετηρίασης» ανοίγει το επίσημο παράθυρο των Windows. «Εφαρμογή Προφίλ Χαμηλής Χρήσης Πόρων» εφαρμόζει ΟΛΑ τα tweaks αυτής της κάρτας μαζί με ένα κλικ, μετά από επιβεβαίωση.",
                ["Help_Tweaks_Encryption"] = "«Άνοιγμα Ρυθμίσεων Κρυπτογράφησης» ανοίγει απευθείας τη σελίδα BitLocker/Κρυπτογράφησης Συσκευής των επίσημων Ρυθμίσεων Windows - η ίδια η εφαρμογή δεν αλλάζει τίποτα εδώ.",
                ["Help_Tweaks_VisualEffects"] = "Τρία έτοιμα προφίλ με ένα κλικ, μετά από επιβεβαίωση: «Καλύτερη Εμφάνιση» (όλα τα οπτικά εφέ ενεργά), «Καλύτερη Απόδοση» (όλα απενεργοποιημένα, ελαφρύτερο UI), «Ισορροπημένο» (Windows επιλέγει αυτόματα).",
                ["Help_Tweaks_RightClick"] = "Δύο διακόπτες για ενσωματωμένες επιλογές δεξιού κλικ: «Ιδιοκτησία» και «Άνοιγμα PowerShell Εδώ» (αντικατοπτρίζουν την πραγματική τρέχουσα κατάσταση μητρώου). Από κάτω, «Προσθήκη Νέας Επιλογής» ανοίγει διάλογο για να δημιουργήσετε δικές σας προσαρμοσμένες καταχωρήσεις μενού δεξιού κλικ (κείμενο+εντολή+εμβέλεια), με κουμπί «Αφαίρεση» ανά καταχωρημένη επιλογή στη λίστα.",
                ["Help_BloatwareTitle"] = "Εφαρμογές & Bloat",
                ["Help_BloatwareDesc"] = "Αφαίρεση/επανεγκατάσταση ενσωματωμένων στοιχείων Windows (Copilot, Xbox Game Bar, News & Weather, Windows Media Player, Photo Viewer, HEVC codecs). Προτεινόμενες Εφαρμογές σε 7 ομαδοποιημένες κατηγορίες με πραγματικά λογότυπα (λήψη μία φορά, τοπική αποθήκευση) - εγκατάσταση/αφαίρεση μέσω winget. Βαθιά Απεγκατάσταση με προαιρετική αναζήτηση υπολειπόμενων φακέλων.",
                ["Help_Bloat_Builtin"] = "6 σταθερές καταχωρήσεις (Copilot, Xbox Game Bar, News & Weather, Windows Media Player Legacy, Photo Viewer Classic, HEVC codecs) - κάθε μία με δικό της κουμπί «Εγκατάσταση» και «Αφαίρεση», πλήρως αναστρέψιμα.",
                ["Help_Bloat_Recommended"] = "Εφαρμογές ομαδοποιημένες κατά κατηγορία (Browsers/Συμπίεση/Πολυμέσα/Επικοινωνία/Εργαλεία/Έγγραφα/System Libs). Το κουμπί στην κεφαλίδα κάθε ομάδας εγκαθιστά ΟΛΕΣ τις μη εγκατεστημένες εφαρμογές της ομάδας μαζί. Κάθε εφαρμογή έχει το δικό της κουμπί Εγκατάσταση/Απεγκατάσταση (μέσω winget) - το K-Lite Codec Pack ρυθμίζει επιπλέον προεπιλεγμένο player. Το πλαίσιο αναζήτησης φιλτράρει κατά όνομα.",
                ["Help_Bloat_UwpManager"] = "Το κουμπί ανοίγει ξεχωριστό παράθυρο αφιερωμένο στη διαχείριση εγκατεστημένων εφαρμογών UWP/Store.",
                ["Help_Bloat_DeepUninstall"] = "«Ανανέωση Λίστας» διαβάζει όλες τις εγκατεστημένες εφαρμογές από το μητρώο απεγκατάστασης και επισημαίνει όσες τρέχουν ΚΑΙ στην εκκίνηση. Το πλαίσιο αναζήτησης φιλτράρει κατά όνομα. Το κουμπί απεγκατάστασης ανά εφαρμογή τρέχει την πραγματική ρουτίνα απεγκατάστασής της, μετά ψάχνει για υπολειπόμενους φακέλους και προτείνει τη διαγραφή τους (με δική σας επιβεβαίωση).",
                ["Help_AdvancedTitle"] = "Προηγμένα Εργαλεία",
                ["Help_AdvancedDesc"] = "Συντήρηση & Διάγνωση Συστήματος (Πλήρης Συντήρηση, Event Logs, Deep Diagnostics, Windows Update repair/reset, Group Policy Editor κ.ά.). Εργαλειοθήκη γρήγορης πρόσβασης σε ενσωματωμένα εργαλεία Windows + επανεκκίνηση GPU driver. Πλήρης, αναζητήσιμη λίστα ΟΛΩΝ των πρόσθετων λειτουργιών Windows. Διαχείριση Συσκευών-Φαντασμάτων.",
                ["Help_Adv_Maintenance"] = "11 ανεξάρτητα κουμπιά: Πλήρης Συντήρηση (Temp+SFC+DISM μαζί), Ενεργοποίηση Προνομίων Συστήματος, Επαναφορά Δικτύου & Winsock, Καθαρισμός Event Logs (ζητά επιβεβαίωση), Βελτιστοποίηση Μνήμης (GC), Deep Diagnostics Report, Διαχείριση Οδηγών (ανοίγει Device Manager), Επιδιόρθωση Windows Update, Αναφορά Συστήματος, Reset Υπηρεσιών Windows Update, Καθαρισμός Διαπιστευτηρίων Xbox, και Εγκατάσταση Group Policy Editor (για εκδόσεις Home που δεν τον έχουν).",
                ["Help_Adv_Toolbox"] = "Γρήγορες συντομεύσεις για ενσωματωμένα εργαλεία Windows: Snipping Tool, Σημειωματάριο, Αριθμομηχανή, Πίνακας Ελέγχου, Διαχείριση Εργασιών, Επεξεργαστής Μητρώου (ζητά επιβεβαίωση - προσοχή), και Επανεκκίνηση GPU Driver (ισοδύναμο Win+Ctrl+Shift+B).",
                ["Help_Adv_OptionalFeatures"] = "«Ανανέωση Λίστας» διαβάζει ΟΛΕΣ τις πρόσθετες λειτουργίες Windows (DISM) - σε αποτυχία δείχνει το πραγματικό μήνυμα σφάλματος, όχι γενική εικασία. Τα μπλε chips είναι συντομεύσεις σε δημοφιλείς λειτουργίες - κλικ συμπληρώνει αυτόματα το πλαίσιο αναζήτησης. Κάθε λειτουργία στη λίστα έχει δικό της διακόπτη ενεργοποίησης/απενεργοποίησης, μετά από επιβεβαίωση.",
                ["Help_Adv_GhostDevices"] = "«Σάρωση» εντοπίζει συσκευές που δεν είναι πλέον φυσικά συνδεδεμένες αλλά παραμένουν καταχωρημένες στη Διαχείριση Συσκευών (π.χ. παλιά USB). «Αφαίρεση» ανά συσκευή τις διαγράφει οριστικά από το σύστημα, μετά από επιβεβαίωση.",
                ["Help_Adv_ScheduledTasks"] = "«Σάρωση» δείχνει προγραμματισμένες εργασίες ΤΡΙΤΩΝ (εξαιρούνται οι επίσημες εργασίες των ίδιων των Windows). Κάθε εργασία έχει διακόπτη - η απενεργοποίηση δεν διαγράφει την εργασία, απλά τη σταματά (ασφαλώς αναστρέψιμο).",
                ["Help_Adv_BootTimeline"] = "Καθαρά πληροφοριακό - δείχνει τον συνολικό χρόνο εκκίνησης Windows ανά επανεκκίνηση (ίδιο event που τροφοδοτεί το Reliability Monitor), ώστε να δείτε αν η εκκίνηση επιβραδύνεται με τον καιρό. «Ανανέωση» ξαναδιαβάζει τα πιο πρόσφατα δεδομένα.",
                ["Help_Adv_Autologon"] = "Ρυθμίζει αυτόματη σύνδεση χρήστη χωρίς κωδικό στην εκκίνηση των Windows. ΠΡΟΣΟΧΗ (βλ. κόκκινη προειδοποίηση στην ίδια την κάρτα): ο κωδικός αποθηκεύεται σε ΚΑΘΑΡΟ ΚΕΙΜΕΝΟ στο μητρώο - περιορισμός του ίδιου του μηχανισμού AutoAdminLogon, δεν αποφεύγεται. Μην το χρησιμοποιήσετε σε κοινόχρηστο ή ευαίσθητο υπολογιστή. Συμπληρώστε όνομα χρήστη+κωδικό και πατήστε «Ενεργοποίηση» ή «Απενεργοποίηση».",
                ["Help_SystemTitle"] = "Σύστημα",
                ["Help_SystemDesc"] = "Εφαρμογές Εκκίνησης (toggle ανά μία, αναστρέψιμο). Διεργασίες Συστήματος (25 πιο βαριές, με ασφαλή τερματισμό). Αποθηκευτικός Χώρος - διπλότυπα/μεγάλα αρχεία στους προσωπικούς σας φακέλους, πάντα μέσω Κάδου Ανακύκλωσης. Σημεία Επαναφοράς Συστήματος. Βελτιστοποίηση Υπηρεσιών (σε Χειροκίνητο). Benchmark Ταχύτητας Δίσκου.",
                ["Help_Sys_MyDevice"] = "Οκτώ πληροφοριακές κάρτες (Μητρική, Δίσκοι, Λειτουργικό, Δίκτυο, CPU, Μπαταρία, RAM, GPU) φορτώνονται αυτόματα μία φορά κατά το άνοιγμα της καρτέλας - καθαρά πληροφοριακές, καμία ρύθμιση εδώ. Το κουμπί «Εξαγωγή» πάνω-δεξιά αποθηκεύει ΟΛΗ αυτή την πληροφορία σε ένα πραγματικό αρχείο PDF στην Επιφάνεια Εργασίας και το ανοίγει αυτόματα.",
                ["Help_Sys_Startup"] = "«Ανανέωση» ξαναδιαβάζει τη λίστα εφαρμογών εκκίνησης, με εκτίμηση καθυστέρησης ανά εφαρμογή όπου είναι διαθέσιμη. Κάθε εφαρμογή έχει δικό της διακόπτη - πλήρως αναστρέψιμο.",
                ["Help_Sys_Processes"] = "«Απελευθέρωση Μνήμης» περιορίζει το working set εφαρμογών παρασκηνίου (ΔΕΝ τις τερματίζει), μετά από επιβεβαίωση. «Ανανέωση» ξαναφορτώνει τη λίστα διεργασιών και καταγράφει δείγματα μνήμης για το ιστορικό τάσης. Κάθε διεργασία (εκτός κρίσιμων συστήματος) έχει κουμπί «Τερματισμός», μετά από επιβεβαίωση.",
                ["Help_Sys_Storage"] = "«Εύρεση Διπλότυπων»/«Εύρεση Μεγάλων Αρχείων» σαρώνουν τους προσωπικούς σας φακέλους. Αν εντοπιστεί OneDrive/Google Drive/Dropbox, εμφανίζονται επιπλέον κουμπιά ειδικά για αυτούς τους φακέλους συγχρονισμού. Κάθε αποτέλεσμα δείχνει μια εκτίμηση «AI-στυλ» ασφάλειας διαγραφής (Χαμηλή/Μέτρια/Υψηλή, βάσει ηλικίας+τύπου αρχείου - όχι πραγματικό ML). Το κουμπί Κάδου στέλνει το αρχείο στον Κάδο Ανακύκλωσης (αναστρέψιμο)· το κόκκινο κουμπί Καταστροφής το διαγράφει ΜΟΝΙΜΑ με 3 περάσματα επικάλυψης (μη αναστρέψιμο, ζητά επιβεβαίωση - δεν είναι εγγυημένο σε SSD/NVMe λόγω wear-leveling).",
                ["Help_Sys_RestorePoints"] = "«Δημιουργία Σημείου» φτιάχνει νέο σημείο επαναφοράς τώρα. «Ανανέωση» ξαναφορτώνει τη λίστα υπαρχόντων σημείων. «Ρυθμίσεις Προστασίας» ανοίγει το επίσημο παράθυρο Windows. «Επαναφορά» σε ένα σημείο ενεργοποιεί πραγματική επαναφορά συστήματος (επανεκκίνηση!) - ζητά έντονη προειδοποίηση πριν προχωρήσει.",
                ["Help_Sys_Services"] = "«Ανανέωση» φορτώνει τις υπηρεσίες Windows. Κάθε υπηρεσία έχει διακόπτη - η απενεργοποίηση θέτει τον τύπο εκκίνησης σε Χειροκίνητο (η υπηρεσία ΔΕΝ σταματά αμέσως, απλά δεν θα ξεκινήσει αυτόματα στην επόμενη εκκίνηση), η ενεργοποίηση επαναφέρει τον αρχικό τύπο εκκίνησης.",
                ["Help_Sys_Benchmark"] = "Επιλέξτε δίσκο από τη λίστα και πατήστε «Έναρξη Δοκιμής» για πραγματική μέτρηση ταχύτητας εγγραφής/ανάγνωσης (MB/s).",
                ["Help_SecondaryTitle"] = "Δευτερεύοντα Παράθυρα",
                ["Help_SecondaryDesc"] = "Κρυφές Λειτουργίες (ViVeTool) - πειραματικά χαρακτηριστικά Windows, κατεβαίνει αυτόματα το επίσημο εργαλείο· Ρυθμίσεις Εμφάνισης - 22 θέματα (incl. Windows Classic), κινούμενα φόντα, μενού, γλώσσα· Διαχείριση UWP Εφαρμογών· Ιστορικό Ενεργειών· Ιστορικό Εκδόσεων.",
                ["Help_SafetyTitle"] = "Ασφάλεια & Ρίσκο",
                ["Help_SafetyDesc"] = "Καμία ενέργεια δεν εγκαθιστά/διαγράφει τίποτα σιωπηλά χωρίς επιβεβαίωση - οι πιο ριψοκίνδυνες λειτουργίες (π.χ. λήψη οδηγού εκτός Windows Update, επαναφορά συστήματος) προτείνουν ή απαιτούν πρώτα σημείο επαναφοράς/ρητή επιβεβαίωση.",
                ["License_Title"] = "Άδεια Χρήσης",
                ["License_Intro"] = "Αυτή η εφαρμογή διανέμεται ΔΩΡΕΑΝ ως λογισμικό ανοιχτού κώδικα, υπό την Άδεια MIT (MIT License) - μία από τις πιο απλές και επιτρεπτικές άδειες ανοιχτού κώδικα. Μπορείτε να τη χρησιμοποιείτε, να την τροποποιείτε και να τη διανέμετε ελεύθερα.\n\nΣΗΜΑΝΤΙΚΟ - ΑΠΟΠΟΙΗΣΗ ΕΥΘΥΝΗΣ: Το λογισμικό παρέχεται «ΩΣ ΕΧΕΙ», χωρίς καμία εγγύηση οποιουδήποτε είδους. Ο δημιουργός δεν φέρει ΚΑΜΙΑ ευθύνη για οποιαδήποτε ζημιά, απώλεια δεδομένων ή προβλήματα στο σύστημά σας που τυχόν προκύψουν από τη χρήση της εφαρμογής. Η χρήση γίνεται με αποκλειστική ευθύνη του χρήστη.",
                ["License_Credit"] = "Ορισμένες ιδέες σχεδίασης εμπνεύστηκαν από το ανοιχτού κώδικα εργαλείο Windows Maintenance Tool (github.com/ios12checker/Windows-Maintenance-Tool), επίσης υπό άδεια MIT.",
                ["License_ThirdPartyTitle"] = "Στοιχεία Τρίτων",
                ["License_ThirdPartyText"] = "Η εφαρμογή περιλαμβάνει επίσης τις παρακάτω βιβλιοθήκες ανοιχτού κώδικα, η καθεμία υπό τη δική της άδεια:\n\n• LibreHardwareMonitorLib (github.com/LibreHardwareMonitor/LibreHardwareMonitor) - Mozilla Public License 2.0. Χρησιμοποιείται για την ανάγνωση αισθητήρων θερμοκρασίας CPU/GPU/δίσκου. Πλήρες κείμενο άδειας: mozilla.org/MPL/2.0\n\n• PDFsharp (github.com/empira/PDFsharp) - Άδεια MIT, © empira Software GmbH. Χρησιμοποιείται για τη δημιουργία εξαγωγών αναφορών σε PDF.\n\n• .NET / Windows Presentation Foundation runtime - Άδεια MIT, © .NET Foundation και συνεισφέροντες.",
                ["License_Gpl3Note"] = "Επιπλέον, για λόγους πληρότητας, παρατίθεται παρακάτω το πλήρες κείμενο των όρων της GNU General Public License v3.0 (GPL-3.0). Ο ίδιος ο κώδικας της εφαρμογής παραμένει υπό την Άδεια MIT παραπάνω - οι όροι GPL-3.0 παρατίθενται για λόγους αναφοράς και συμβατότητας αδειών.",
