                ["Appr_SkinClassic"] = "Normal (whichever theme you've chosen in Themes)",
                ["Appr_SkinClassicTip"] = "The normal layout - tab strip and/or sidebar menu, depending on the Menu settings above.",
                ["Appr_SkinPcManager"] = "Microsoft PC Manager (vertical icon bar, no tab strip/sidebar menu)",
                ["Appr_SkinPcManagerTip"] = "A full recreation of Microsoft PC Manager's layout/appearance - automatically selects the matching theme.",
                ["Appr_SkinWindowsClassic"] = "Windows Classic (square appearance, only the classic menu bar)",
                ["Appr_SkinWindowsClassicTip"] = "An authentic Windows Classic look (as available up through Vista) - square corners/buttons, no tab strip/sidebar menu, only the classic menu bar (always visible).",
                ["Appr_SkinDesc"] = "The \"Microsoft PC Manager\" skin automatically selects the matching theme and changes the main window's layout to a vertical icon bar. \"Windows Classic\" selects the matching theme, hides the tab strip/hamburger/sidebar menu, and leaves ONLY the classic menu bar, always visible. \"Normal\" restores your previous theme.",
                ["Appr_LanguageTab"] = "Language",
                ["Appr_AppLanguage"] = "App Language",
