        public static void LoadPersisted() => Current = AppSettingsService.Current.Language;

        public static void SetLanguage(string code)
        {
            if (!Translations.ContainsKey(code)) return;
            Current = code;
            AppSettingsService.Current.Language = code;
            AppSettingsService.Save();
            Changed?.Invoke();
            // Binding.IndexerName ("Item[]") ενημερώνει ΚΑΘΕ ενεργό indexer-binding ταυτόχρονα -
            // αυτό είναι που κάνει την αλλαγή γλώσσας να φαίνεται ζωντανά παντού.
            Instance.PropertyChanged?.Invoke(Instance, new PropertyChangedEventArgs(System.Windows.Data.Binding.IndexerName));
        }

        public static string T(string key) =>
            Translations.TryGetValue(Current, out var dict) && dict.TryGetValue(key, out var v) ? v
            : Translations["el"].TryGetValue(key, out var fallback) ? fallback : key;
    }
